    "sec3Title": "Zero-Disk In-Memory Streaming Architecture",
    "sec3P1": "Traditional file encryption tools operate on a \"decrypt-to-disk\" model: when a user clicks an encrypted video, the software creates a decrypted file in <code>C:\\Users\\...\\AppData\\Local\\Temp</code>, hands the file path to a system media player, and attempts to delete it upon window close.",
    "sec3P2": "This legacy architecture creates catastrophic privacy vulnerabilities:",
    "sec3Vuln1": "<strong>Forensic Disk Residue:</strong> Even when deleted, magnetic and flash drives retain unallocated clusters that forensic recovery tools (EnCase, FTK, PhotoRec) reconstruct with ease.",
    "sec3Vuln2": "<strong>OS Thumbnail & Event Logging:</strong> Windows Shell and macOS Spotlight actively crawl temp directories, generating unencrypted thumbnail caches and shellbag records.",
    "sec3Vuln3": "<strong>Process Crashes & Orphaned Files:</strong> If the application crashes or system power cuts out, plaintext files remain permanently exposed on disk.",
    "sec3P3": "<strong>The HiddenData Zero-Disk Solution:</strong> Both the Android app and Chrome Side Panel employ an in-memory streaming pipeline:",
    "sec3P4": "When viewing a 4K 60fps video, HiddenData requests chunks sequentially or randomly via byte-range requests. As each 64KB chunk is authenticated and decrypted in RAM, it is fed directly into a browser <code>MediaSource</code> buffer or Android <code>MediaCodec</code> pipeline. When the user navigates away, the typed array buffers are overwritten with zero bytes (<code>Arrays.fill(buffer, 0)</code>) before memory deallocation.",
