    "sec4KeySlotP1": "In legacy encrypted vaults, changing a master password requires re-encrypting the entire storage drive. If a user holds 500GB of 4K video, password rotation requires hours of heavy disk I/O, generating severe wear on SSD flash cells and extreme risk of data corruption if power is interrupted.",
