    "thScopeRisk": "プライバシーリスク評価",
    "scopeHdName": "HiddenDataの基本方針",
    "scopeHdAccess": "HiddenDataが直接作成した暗号化ファイル（.enc）および設定ファイルのみ。既存のGoogleドライブファイルへのアクセス権はゼロ。",
    "scopeHdRisk": "CASAセキュリティ審査合格 / リスク皆無",
    "scopeLegacyName": "一般的な金庫アプリ",
    "scopeLegacyAccess": "ユーザーのGoogle Drive全体に対する無制限の読み取り・書き込み・削除権限。",
    "scopeLegacyRisk": "深刻なセキュリティリスク",
    "sec5P2": "HiddenDataは最小権限の原則（Least Privilege）を厳格に順守します：",
    "sec5List1": "既存の個人ファイルへのアクセス皆無：HiddenData以外のGoogle Docs、スプレッドシート、写真などを閲覧・検索する権限は一切持ちません。",
    "sec5List2": "100% 暗号化テキスト保管：Google DriveのHiddenData_Vaultフォルダに保存される全ファイルは、端末側で暗号化された乱数バイナリブロックです。",
    "sec5List3": "中継サーバーのないP2P通信：ユーザーの端末とGoogle公式REST APIエンドポイント間でTLS 1.3により直接通信し、開発元のサーバーは介在しません。",
    "sec6Title": "クロスプラットフォーム Pro ライセンス完全性検証",
    "sec6P1": "HiddenDataは中央のユーザー登録データベースを持ちません。Lemon SqueezyでProライセンスを購入した際、追跡サーバーなしでPCとスマホの認証をどのように同期しているのでしょうか？",
    "sec6P2": "その答えが「V2電子署名ライセンスエンベロープ」（.hiddendata_pro_license.json）です：",
    "sec6List1": "購入完了時、決済Webhookが購入者のGoogleメールと注文番号を組み合わせたHMAC-SHA256署名を発行します。",
    "sec6List2": "この暗号化トークンは、ユーザーのプライベートなGoogle Drive金庫フォルダに安全に保存されます。",
    "sec6List3": "AndroidアプリまたはPC拡張機能の起動時、オフラインで電子署名が検証され、追加課金なしで両方のプラットフォームでPro機能が永久に有効化されます。",
