    "sec5P2": "HiddenData 嚴格落實最小權限原則 (Least Privilege)：",
    "sec5List1": "零存取個人檔案：HiddenData 無法檢視、搜尋或接觸使用者在 Google Drive 中原有的任何 Google Docs、試算表或照片。",
    "sec5List2": "100% 密文儲存：儲存於 HiddenData_Vault 資料夾的所有檔案均已在本地完成高強度加密，Google 伺服器僅能看到隨機二進位區塊。",
    "sec5List3": "無中介伺服器傳輸：使用者裝置與 Google 官方 REST API 透過 TLS 1.3 直接對接，絕無開發商代理伺服器經手資料。",
    "sec6Title": "跨平台 Pro 授權防偽驗證協定",
    "sec6P1": "HiddenData 不設中央會員帳號資料庫。當使用者透過 Lemon Squeezy 購買 Pro 終身授權時，系統如何在無追蹤伺服器的情況下安全同步電腦與手機？",
    "sec6P2": "答案是 V2 數位簽章授權封套 (.hiddendata_pro_license.json)：",
    "sec6List1": "購買完成時，付款 Webhook 會發布綁定使用者 Google 信箱與訂單編號的 HMAC-SHA256 數位簽章。",
    "sec6List2": "該加密授權權杖會安全存放在使用者個人的 Google Drive 保險庫資料夾中。",
    "sec6List3": "當 Android App 或 Chrome 擴充功能開啟時，會離線驗證該數位簽章，永久啟用雙平台 Pro 功能，無需後續週期性驗證。",
