    "secArchHeroSub": "Un análisis técnico profundo de la bóveda de conocimiento cero de HiddenData: streaming AEAD en bloques independientes de 64KB, 0B de escritura en disco, actualización atómica de claves V3 y aislamiento de mínimo privilegio con Google Drive.",
