    "secArchMetaStandard": "NIST SP 800-38D AES-256-GCM",
    "metricZeroDiskTitle": "Residuo en Disco",
    "metricZeroDiskSub": "Descifrado estrictamente en TypedArray de memoria RAM",
    "metricChunkTitle": "Tamaño de Bloque AEAD",
    "metricChunkSub": "Etiqueta de autenticación GCM independiente por bloque",
    "metricPbkdfTitle": "Iteraciones PBKDF2",
    "metricPbkdfSub": "HMAC-SHA256 con sal CSPRNG de 16 bytes",
    "metricThumbTitle": "Lectura de Miniatura",
    "metricThumbSub": "Extracción en 0.005s sin escanear el archivo completo",
    "metricRekeyTitle": "Actualización KeySlot",
    "metricRekeySub": "Cambio de contraseña actualiza solo el encabezado de 49B en 0.001s",
    "metricScopeTitle": "Alcance Mínimo",
    "metricScopeSub": "0% de acceso a archivos existentes en Google Drive",
    "sec1Title": "Resumen Ejecutivo y Garantías Fundamentales",
    "sec1P1": "HiddenData es una bóveda multimedia criptográfica de conocimiento cero (Zero-Knowledge) de nivel empresarial, diseñada específicamente para streaming de imágenes de alto rendimiento, GIFs animados y video 4K UHD en navegadores de escritorio (Panel Lateral de Chrome) y Android.",
    "sec1P2": "A diferencia de las herramientas convencionales que descifran archivos en carpetas temporales del sistema (/tmp, AppData/Local/Temp o caché de aplicaciones), HiddenData elimina por completo la huella en disco. Todo el descifrado ocurre bajo demanda en memoria RAM volátil, seguido de una eliminación criptográfica instantánea (Zeroization) al cerrar.",
    "sec1CalloutTitle": "Axioma Fundamental de Conocimiento Cero",
    "sec1CalloutDesc": "Ni los desarrolladores, ni Google Drive, ni ningún intermediario de red poseen acceso a las contraseñas maestras, claves derivadas o archivos en claro. Si el usuario olvida su contraseña maestra, la recuperación matemática es imposible. No existen claves de depósito, preguntas de recuperación ni puertas traseras.",
    "sec2Title": "Primitivas Criptográficas y Derivación de Claves",
    "sec2P1": "Todas las operaciones criptográficas cumplen rigurosamente con los estándares del NIST y los protocolos modernos de cifrado autenticado (AEAD).",
    "thCryptoParam": "Parámetro Criptográfico",
    "thCryptoStandard": "Estándar / Implementación",
    "thCryptoPurpose": "Propósito y Justificación de Seguridad",
    "rowCipherName": "Cifrado Simétrico",
    "rowCipherDesc": "Galois/Counter Mode ofrece confidencialidad ultrarrápida acelerada por hardware y autenticación de integridad de 128 bits (AEAD).",
    "rowKeyLength": "Longitud de Clave",
    "rowKeyLengthDesc": "Clave máxima AES de 256 bits, resistente contra ataques de computación cuántica con el algoritmo de Grover (seguridad cuántica efectiva de 128 bits).",
    "rowKdfName": "Función de Derivación (KDF)",
    "rowKdfDesc": "Extiende la contraseña a una Clave de Cifrado de Claves (KEK) de 256 bits, evitando ataques de tablas rainbow en GPU/ASIC.",
    "rowIterations": "Factor de Trabajo KDF",
    "rowIterationsDesc": "100,000 iteraciones imponen un costo extremo a los ataques de fuerza bruta mientras mantienen el desbloqueo local en menos de 250 ms.",
    "rowSalt": "Generación de Sal (Salt)",
    "rowSaltDesc": "Generada por archivo mediante generadores aleatorios criptográficamente seguros (crypto.getRandomValues / SecureRandom).",
    "rowChunkAead": "Nonce de Bloque AEAD",
    "rowChunkAeadDesc": "IV Base de 12B combinado mediante XOR con un contador de 64 bits para evitar la reutilización de nonces y ataques de reordenamiento.",
    "rowVerifier": "Verificador Instantáneo",
    "rowVerifierDesc": "Comprueba la validez de la contraseña maestra en 0.001s sin intentar descifrar el contenido completo.",
    "rowLicenseSign": "Verificación de Licencia",
    "rowLicenseSignDesc": "Arquitectura de firma HMAC-SHA256 que sincroniza licencias Pro entre Android y PC sin servidores de cuentas centrales.",
    "sec2AadTitle": "Protección con Datos Autenticados Adicionales (AAD)",
    "sec2AadDesc": "Para evitar que un atacante intercambie bloques entre archivos cifrados diferentes, HiddenData vincula los primeros 32 bytes del encabezado como Datos Autenticados Adicionales (AAD) en cada bloque de 64KB. Cualquier alteración invalida de inmediato la etiqueta de autenticación GCM.",
    "sec3Title": "Arquitectura de Streaming Cero-Disco en Memoria",
    "sec3P1": "Las herramientas tradicionales operan con un modelo de descifrado en disco: al abrir un video cifrado, crean un archivo temporal en claro, lo pasan a un reproductor externo e intentan borrarlo al cerrar.",
    "sec3P2": "Esta arquitectura antigua genera graves vulnerabilidades de privacidad:",
    "sec3Vuln1": "Residuo Forense en Disco: Aunque se borre, los clústeres no asignados retienen los datos originales, que herramientas como EnCase o FTK recuperan fácilmente.",
    "sec3Vuln2": "Caché de Miniaturas del SO: Windows Shell y macOS Spotlight indexan de inmediato las carpetas temporales, creando miniaturas sin cifrar y registros Shellbag.",
    "sec3Vuln3": "Archivos Huérfanos por Cierre Inesperado: Si la app falla o se corta la energía, los archivos en claro permanecen expuestos indefinidamente en el disco.",
    "sec3P3": "La Solución Cero-Disco de HiddenData: Tanto Android como Chrome Side Panel utilizan una canalización en memoria:",
    "sec3P4": "Al reproducir video 4K a 60fps, HiddenData solicita datos en bloques de 64KB. Cada bloque se autentica y descifra en memoria RAM y se envía directamente al búfer MediaSource del navegador o MediaCodec en Android. Al cerrar, los búferes se sobrescriben de inmediato con ceros mediante Arrays.fill(buffer, 0).",
    "sec4Title": "Especificación Binaria V3 y KeySlotManager",
    "sec4P1": "Para permitir la interoperabilidad total entre Android y Chrome en PC, HiddenData utiliza un formato de contenedor binario estandarizado: el Sobre Criptográfico V3.",
    "sec4KeySlotTitle": "KeySlotManager y Cambio de Clave Atómico en 0.001s",
    "sec4KeySlotP1": "En las bóvedas tradicionales, cambiar la contraseña maestra requiere descifrar y volver a cifrar cientos de gigabytes, generando horas de desgaste en el SSD y riesgo de corrupción ante cortes de energía.",
    "sec4KeySlotP2": "HiddenData resuelve esto mediante el cifrado de sobre con KeySlotManager. El contenido se cifra con una Clave Maestra (MK) aleatoria de 256 bits, y solo esa MK se cifra con la clave derivada (KEK) y se guarda en el encabezado.",
    "sec4RekeyTitle": "Rendimiento de Cambio Atómico: Exactamente 0.001s",
    "sec4RekeyDesc": "Al cambiar la contraseña, HiddenData vuelve a cifrar únicamente la Clave Maestra de 32 bytes en el encabezado. Los gigabytes de contenido permanecen intactos. La actualización toma 1 milisegundo por archivo con cero riesgo de corrupción.",
    "sec4ThumbTitle": "Miniatura Embebida en Encabezado V3 (Vista Previa en 0.005s)",
    "sec4ThumbP1": "Para lograr un desplazamiento suave a 60fps en galerías con miles de archivos, el encabezado V3 incluye una miniatura WebP cifrada de 128x128. Solo se leen los primeros ~2KB de cada archivo, cargando la galería en 0.005 segundos.",
    "sec5Title": "Aislamiento de Mínimo Privilegio en Google Drive (drive.file)",
    "sec5P1": "Muchas aplicaciones de copia de seguridad solicitan acceso completo a Google Drive (.../auth/drive), lo que les permite leer, modificar o eliminar todos los documentos privados y fotos de la cuenta.",
    "thScopeType": "Tipo de Alcance",
    "thScopeUrl": "URI del Alcance OAuth 2.0",
    "thScopeAccess": "Límite de Acceso Concedido",
    "thScopeRisk": "Evaluación de Riesgo",
    "scopeHdName": "Política HiddenData",
