    "scopeHdRisk": "Auditado por CASA / Riesgo Cero",
    "scopeLegacyName": "Bóvedas Tradicionales",
    "scopeLegacyAccess": "Acceso total sin restricciones para leer, editar y borrar todo el Google Drive del usuario.",
    "scopeLegacyRisk": "Peligro Crítico de Seguridad",
    "sec5P2": "HiddenData aplica estrictamente el Principio de Mínimo Privilegio:",
    "sec5List1": "Cero acceso a archivos personales: HiddenData no puede ver, buscar ni acceder a documentos, hojas de cálculo o fotos existentes en su Drive.",
    "sec5List2": "100% Cifrado en Almacenamiento: Cada archivo subido a la carpeta HiddenData_Vault ya está fuertemente cifrado localmente como bloques binarios aleatorios.",
    "sec5List3": "Sin servidores intermediarios: La comunicación se realiza directamente entre su dispositivo y la API REST oficial de Google mediante TLS 1.3.",
    "sec6Title": "Protocolo de Verificación de Licencia Pro Multiplataforma",
    "sec6P1": "HiddenData opera sin bases de datos de usuarios centrales. Al adquirir una licencia de por vida a través de Lemon Squeezy, ¿cómo se sincroniza la activación entre PC y Android de forma segura sin servidores de rastreo?",
    "sec6P2": "La respuesta es el Sobre de Licencia con Firma Digital V2 (.hiddendata_pro_license.json):",
    "sec6List1": "El webhook de pago emite una firma HMAC-SHA256 vinculando el correo de Google y el ID del pedido.",
    "sec6List2": "El token de licencia cifrado se guarda directamente en la carpeta privada de la bóveda en Google Drive.",
    "sec6List3": "Al abrir la app o extensión, la firma criptográfica se verifica localmente sin conexión, desbloqueando permanentemente Pro en ambas plataformas.",
