    "metricScopeSub": "0% Zugriff auf bestehende Google Drive-Dateien",
    "sec1Title": "Zusammenfassung & Grundlegende Sicherheitsgarantien",
    "sec1P1": "HiddenData ist ein hochsicherer Zero-Knowledge-Medientresor für Unternehmen, der speziell für hochauflösende Bilder, animierte GIFs und 4K-UHD-Videostreaming in Desktop-Browsern (Chrome-Seitenleiste) und auf Android-Geräten entwickelt wurde.",
    "sec1P2": "Im Gegensatz zu herkömmlichen Verschlüsselungstools, die Dateien in temporäre Verzeichnisse (/tmp, AppData/Local/Temp oder App-Cache) schreiben, hinterlässt HiddenData keinerlei Spuren auf dem Datenträger. Die Entschlüsselung erfolgt rein im flüchtigen Arbeitsspeicher (RAM) bei Bedarf, gefolgt von einer sofortigen kryptografischen Überschreibung (Zeroization) beim Schließen.",
    "sec1CalloutTitle": "Fundamentales Zero-Knowledge-Axiom",
    "sec1CalloutDesc": "Weder Entwickler, noch Google Drive oder Netzbetreiber haben Zugriff auf Master-Passwörter, abgeleitete Schlüssel oder Klartextdaten. Bei Verlust des Master-Passworts ist eine Wiederherstellung mathematisch unmöglich. Es existieren keinerlei Treuhand-Schlüssel oder Hintertüren.",
    "sec2Title": "Kryptografische Primitive & Schlüsselableitung",
    "sec2P1": "Alle kryptografischen Operationen entsprechen streng den Richtlinien des NIST und modernen Standards für authentifizierte Verschlüsselung (AEAD).",
    "thCryptoParam": "Kryptografischer Parameter",
    "thCryptoStandard": "Standard / Implementierung",
    "thCryptoPurpose": "Sicherheitszweck & Begründung",
    "rowCipherName": "Symmetrische Chiffre",
    "rowCipherDesc": "Galois/Counter Mode bietet hardwarebeschleunigte Vertraulichkeit und 128-Bit-Integritätsauthentifizierung (AEAD).",
    "rowKeyLength": "Schlüssellänge",
    "rowKeyLengthDesc": "Maximale 256-Bit-Schlüssellänge, resistent gegen Angriffe mit Grovers Quantenalgorithmus (effektive 128-Bit-Quantensicherheit).",
    "rowKdfName": "Schlüsselableitungsfunktion (KDF)",
    "rowKdfDesc": "Leitet das Passwort in einen 256-Bit Key Encryption Key (KEK) ab; schützt vor Rainbow-Tables auf GPU/ASIC.",
    "rowIterations": "KDF-Arbeitsfaktor (Iterationen)",
    "rowIterationsDesc": "100.000 Runden erzwingen extremen Rechenaufwand bei Brute-Force-Angriffen, halten das lokale Entsperren aber unter 250 ms.",
    "rowSalt": "Salt-Generierung",
    "rowSaltDesc": "Wird pro Datei über kryptografisch sichere Zufallszahlengeneratoren (crypto.getRandomValues / SecureRandom) erzeugt.",
    "rowChunkAead": "Chunk-AEAD-Nonce",
    "rowChunkAeadDesc": "12-Byte Base-IV kombiniert mit 64-Bit-Zähler verhindert Nonce-Wiederverwendung und Chunk-Vertauschungsangriffe.",
    "rowVerifier": "Sofortiger Schlüssel-Prüfer",
    "rowVerifierDesc": "Bestätigt die Gültigkeit des Master-Passworts in 0,001 s, ohne die Nutzlast entschlüsseln zu müssen.",
    "rowLicenseSign": "Lizenzintegritätsprüfung",
    "rowLicenseSignDesc": "HMAC-SHA256-Signaturarchitektur zur sicheren Pro-Lizenzsynchronisation zwischen Android und PC ohne Kontoserver.",
    "sec2AadTitle": "Schutz durch Additional Authenticated Data (AAD)",
    "sec2AadDesc": "Um zu verhindern, dass Angreifer Chunks zwischen verschlüsselten Dateien austauschen, bindet HiddenData die ersten 32 Bytes des Headers als AAD in jeden 64-KB-Chunk ein. Jede Manipulation führt zum sofortigen Fehlschlagen der GCM-Prüfung.",
    "sec3Title": "Zero-Disk In-Memory-Streaming-Architektur",
    "sec3P1": "Traditionelle Tresore entschlüsseln Dateien auf die Festplatte: Beim Öffnen eines Videos wird eine temporäre Klartextdatei angelegt und an einen Medienplayer übergeben, um sie beim Schließen zu löschen.",
    "sec3P2": "Dies führt zu schwerwiegenden Sicherheitslücken:",
    "sec3Vuln1": "Forensische Rückstände: Nach dem Löschen verbleiben Daten in nicht zugewiesenen Clustern, die Forensik-Tools (EnCase, FTK) mühelos wiederherstellen.",
    "sec3Vuln2": "Betriebssystem-Caches: Windows Shell und macOS Spotlight indizieren temporäre Ordner sofort und erzeugen unverschlüsselte Thumbnails und Shellbag-Einträge.",
    "sec3Vuln3": "Verwaiste Dateien bei Absturz: Stürzt das Programm ab oder bricht der Strom ab, verbleiben Klartextdateien dauerhaft auf dem Speicher.",
    "sec3P3": "Die Zero-Disk-Lösung von HiddenData: Sowohl die Android-App als auch die Chrome-Seitenleiste nutzen eine reine RAM-Streaming-Pipeline:",
    "sec3P4": "Beim Abspielen eines 4K-60fps-Videos fordert HiddenData Daten sequentiell in 64-KB-Chunks an. Jeder Chunk wird im RAM entschlüsselt und direkt an den MediaSource-Puffer des Browsers oder an Androids MediaCodec übergeben. Nach dem Schließen werden alle Puffer sofort mit Arrays.fill(buffer, 0) genullt.",
    "sec4Title": "V3-Envelope-Binärformat & KeySlotManager",
    "sec4P1": "Für eine lückenlose Kompatibilität zwischen Android und der PC-Chrome-Erweiterung nutzt HiddenData das standardisierte V3-Kryptografie-Containerformat.",
    "sec4KeySlotTitle": "KeySlotManager & atomare Passwortänderung in 0,001s",
    "sec4KeySlotP1": "Bei herkömmlichen Tresoren erfordert ein Passwortwechsel die vollständige Neuverschlüsselung hunderter Gigabytes. Dies beansprucht Stunden, verschleißt SSDs und birgt Datenverlustrisiken bei Stromausfall.",
    "sec4KeySlotP2": "HiddenData löst dies durch Envelope-Verschlüsselung mit dem KeySlotManager. Die Nutzlast wird mit einem zufälligen 256-Bit Master-Key (MK) verschlüsselt. Nur dieser MK wird mit dem passwortbasierten Schlüssel (KEK) verschlüsselt im Header abgelegt.",
    "sec4RekeyTitle": "Atomare Schlüsselaktualisierung: Exakt 0,001s",
    "sec4RekeyDesc": "Bei einer Passwortänderung verschlüsselt HiddenData lediglich den 32-Byte-Master-Key im Header neu. Die Multi-Gigabyte-Nutzlast bleibt völlig unberührt. Die Aktualisierung erfolgt in 1 Millisekunde ohne Risiko von Datenbeschädigung.",
    "sec4ThumbTitle": "Header-eingebetteter V3-Thumbnail-Block (0,005s Vorschau)",
    "sec4ThumbP1": "Um selbst bei tausenden verschlüsselten Dateien ein flüssiges 60fps-Scrollen zu garantieren, enthält der V3-Header ein verschlüsseltes 128x128 WebP-Thumbnail. Es müssen lediglich die ersten ca. 2 KB gelesen werden, um Galerien in 0,005s darzustellen.",
    "sec5Title": "Google Drive Least-Privilege-Sicherheit (drive.file-Scope)",
    "sec5P1": "Viele Drittanbieter verlangen Vollzugriff auf Google Drive (.../auth/drive), wodurch sie alle persönlichen Dokumente und Fotos im Benutzerkonto einsehen können.",
    "thScopeType": "Berechtigungstyp",
    "thScopeUrl": "OAuth 2.0 Scope-URI",
    "thScopeAccess": "Gewährte Zugriffsgrenzen",
    "thScopeRisk": "Datenschutz-Risikobewertung",
