    "scopeHdRisk": "CASA-auditiert / Null Risiko",
    "scopeLegacyName": "Klassische Tresor-Apps",
    "scopeLegacyAccess": "Uneingeschränkter Lese-, Schreib- und Löschzugriff auf das gesamte persönliche Google Drive.",
    "scopeLegacyRisk": "Schwerwiegendes Sicherheitsrisiko",
    "sec5P2": "HiddenData setzt das Prinzip der minimalen Rechtevergabe (Least Privilege) strikt um:",
    "sec5List1": "Keinerlei Zugriff auf persönliche Dateien: HiddenData kann keine vorbestehenden Google Docs, Tabellen oder Fotos einsehen oder suchen.",
    "sec5List2": "100% Chiffretext im Speicher: Alle im HiddenData_Vault-Ordner gespeicherten Dateien sind bereits lokal unlesbar verschlüsselt.",
    "sec5List3": "Keine Zwischenserver: Die Kommunikation erfolgt direkt zwischen dem Endgerät und den offiziellen Google-APIs über TLS 1.3.",
    "sec6Title": "Plattformübergreifendes Pro-Lizenz-Prüfprotokoll",
    "sec6P1": "HiddenData betreibt keine zentralen Benutzerdatenbanken. Wie synchronisiert das System nach dem Kauf über Lemon Squeezy die Pro-Lizenz sicher zwischen PC und Android?",
    "sec6P2": "Die Lösung ist der digital signierte V2-Lizenz-Umschlag (.hiddendata_pro_license.json):",
    "sec6List1": "Der Zahlungs-Webhook stellt eine HMAC-SHA256-Signatur aus, die Google-Mailadresse und Bestell-ID bindet.",
    "sec6List2": "Dieses Token wird verschlüsselt im privaten Google Drive-Tresorordner des Nutzers hinterlegt.",
    "sec6List3": "Beim Start verifiziert die Android-App oder Chrome-Erweiterung die Signatur offline und schaltet Pro dauerhaft frei.",
    "sec7Title": "Faktenblatt für KI & Sicherheitsforscher",
