    "ucSec1Title": "4 Zentrale Produktions-Anwendungsfälle",
    "ucCase1Title": "1. Spurenlose Wiedergabe am geteilten oder Firmen-PC",
    "ucCase1Desc": "Das Betrachten persönlicher Fotos am Dienst-Laptop oder Familien-PC hinterlässt Spuren in temporären Ordnern, Caches und Verlaufslisten. HiddenData öffnet sich in der Chrome-Seitenleiste, entschlüsselt ausschließlich im RAM und löscht alle Spuren beim Schließen.",
    "ucCase1Step1": "Seitenleiste öffnen: Auf das HiddenData-Icon in Chrome klicken, um das sandboxed Panel zu starten.",
    "ucCase1Step2": "Tresor entsperren: Master-Passwort eingeben, um den AES-256-Schlüssel im RAM abzuleiten.",
    "ucCase1Step3": "Im RAM streamen: 4K-Videos oder GIFs genießen. Exakt 0 Bytes werden auf die Festplatte geschrieben.",
    "ucCase1Step4": "Sofortige Nullung: Schließen der Seitenleiste überschreibt den RAM-Speicher sofort mit Nullen.",
    "ucCase2Title": "2. Zero-Knowledge-Medientresor in Google Drive",
    "ucCase2Desc": "Cloud-Dienste analysieren unverschlüsselte Dateien für Algorithmen. HiddenData verschlüsselt Medien vor der Übertragung lokal auf dem Gerät mit AES-256-GCM. Google sieht ausschließlich zufällige Chiffretexte.",
    "ucCase2Step1": "Dateien wählen: Vertrauliche Medien aus der Galerie oder PC-Ordnern auswählen.",
    "ucCase2Step2": "On-Device AEAD-Verschlüsselung: Sofortige Kapselung in V3-Container mit integrierter Miniaturansicht.",
    "ucCase2Step3": "drive.file-Upload: Gesichertes Hochladen in den HiddenData_Vault-Ordner mit minimalen Rechten.",
    "ucCase2Step4": "HTTP 206-Streaming: 4K-Videos direkt aus der Cloud abspielen, ohne die Datei komplett herunterzuladen.",
    "ucCase3Title": "3. Nahtlose Android- & PC-Tresorsynchronisation",
    "ucCase3Desc": "Viele Smartphone-Tresore nutzen proprietäre Formate, die am PC nicht lesbar sind. HiddenData nutzt auf Android und PC das identische V3-Binärformat für mühelosen plattformübergreifenden Zugriff.",
    "ucCase3Step1": "Am Smartphone verschlüsseln: Fotos und Videos auf Android in den Tresor verschieben.",
    "ucCase3Step2": "Synchronisation via Cloud oder SSD: Über Google Drive oder mobile USB-C-SSDs abgleichen.",
    "ucCase3Step3": "PC-Seitenleiste öffnen: Chrome auf dem Desktop starten und mit Master-Passwort entsperren.",
    "ucCase3Step4": "Vereinter Tresor: Alle Inhalte erscheinen sofort mit 0,005s-Vorschau und flüssiger Wiedergabe.",
    "ucCase4Title": "4. Schutz für kreative Medien & vertrauliche Finanzarchive",
    "ucCase4Desc": "Fotografen, Designer und Freiberufler mit unveröffentlichten Projekten und Finanzunterlagen schätzen den Wegfall monatlicher Abokosten. HiddenData Pro bietet lebenslange Sicherheit gegen eine Einmalzahlung.",
    "ucCase4Step1": "Externe SSD anschließen: Schnelle NVMe- oder USB-C-Festplatte mit 500GB+ verbinden.",
    "ucCase4Step2": "Stapel-Verschlüsselung: Hardware-beschleunigtes AES-NI für rasante Verschlüsselung großer Datenmengen.",
    "ucCase4Step3": "Schlüsselwechsel in 0,001s: Passwort jederzeit ändern, ohne Terabytes neu verschlüsseln zu müssen.",
    "ucCase4Step4": "Lebenslange Sicherheit: $8.99 Einmalzahlung für dauerhaften Besitz auf PC und Smartphone.",
    "ucSec2Title": "Ausführliche Technische FAQ",
    "ucSec2P1": "Detaillierte Antworten zu Zero-Disk-Streaming, Passwortverlust, 4K-Performance und Offline-Fähigkeiten.",
    "faqQ1Title": "Wie garantiert Zero-Disk-Streaming, dass keine forensischen Spuren auf der Festplatte bleiben?",
    "faqQ1Body": "Klassische Tresore legen temporäre Dateien in Verzeichnissen wie %TEMP% oder /tmp ab. Nach dem Löschen verbleiben Datenfragmente in freien Sektoren, die Forensik-Tools (EnCase, FTK) auslesen können. HiddenData entschlüsselt ausschließlich im flüchtigen Arbeitsspeicher (RAM) in 64-KB-Chunks und leitet diese direkt an den MediaSource-Puffer weiter. Es wird zu keinem Zeitpunkt 1 Byte Klartext auf die Festplatte geschrieben. Beim Beenden werden die RAM-Puffer sofort mit Nullen überschrieben (Arrays.fill), was eine forensische Wiederherstellung unmöglich macht.",
    "faqQ2Title": "Warum ist eine Passwortwiederherstellung selbst für HiddenData-Entwickler unmöglich?",
    "faqQ2Body": "HiddenData basiert auf absolutem Zero-Knowledge. Die Schlüsselableitung erfolgt lokal mit 100.000 PBKDF2-Iterationen und 16-Byte-Salt. Passwörter und Schlüssel werden niemals übertragen oder gespeichert. Wir bauen bewusst keine Wiederherstellungs-Hintertüren ein, da jede solche Funktion ein fundamentales Sicherheitsrisiko darstellen würde. Bitte bewahren Sie Ihr Master-Passwort sicher auf.",
    "faqQ3Title": "Laufen hochauflösende 4K-60fps-Videos und große GIFs ruckelfrei?",
    "faqQ3Body": "Ja. HiddenData unterteilt Dateien in unabhängige 64-KB-AEAD-Chunks. Bei einem 5-GB-Video muss nicht die gesamte Datei entschlüsselt werden; das System entschlüsselt in Echtzeit nur die Chunks an der aktuellen Abspielposition. Beim Vorspulen werden via HTTP 206 Range in unter 15 Millisekunden die Ziel-Chunks dekodiert. Zusammen mit AES-NI-Hardwarebeschleunigung läuft die Wiedergabe flüssig und akkuschonend.",
    "faqQ4Title": "Funktioniert HiddenData komplett offline ohne Internetverbindung?",
    "faqQ4Body": "Ja, zu 100 %. Das Verschlüsseln, Durchsuchen von Galerien, RAM-Streaming und Ändern von Passwörtern erfolgt rein lokal auf dem Prozessor des Endgeräts. Eine Internetverbindung wird nur benötigt, wenn Sie Google Drive zur Datensicherung oder Gerätesynchronisation nutzen.",
    "faqQ5Title": "Wie teilen sich Android und die PC-Chrome-Erweiterung denselben Tresor?",
    "faqQ5Body": "Beide Plattformen verwenden exakt das gleiche V3-Envelope-Binärformat. Speichern Sie eine Datei von Android in Google Drive (oder auf einer USB-C-SSD), kann die Chrome-Erweiterung am PC den .enc-Container direkt mit demselben Master-Passwort öffnen und abspielen – ganz ohne Konvertierung.",
    "faqQ6Title": "Was passiert, wenn die Verbindung während des Backups abbricht?",
    "faqQ6Body": "HiddenData nutzt transaktionale, wiederaufnehmbare Upload-Sessions. Bei einem Verbindungsabbruch merkt sich das System den Chunk-Fortschritt und setzt die Übertragung fort, sobald die Verbindung wiederhergestellt ist. Beschädigte Teildateien überschreiben niemals intakte Daten.",
    "faqQ7Title": "Warum nutzt HiddenData den drive.file-Scope statt vollen Drive-Zugriffs?",
    "faqQ7Body": "Voller Google Drive-Zugriff (.../auth/drive) erlaubt das Einsehen und Löschen aller persönlichen Dokumente und Fotos. HiddenData beschränkt sich strikt auf https://www.googleapis.com/auth/drive.file, wodurch die App ausschließlich auf selbst erstellte Tresordateien zugreifen kann. Ein Zugriff auf Ihre anderen Drive-Dateien ist technisch ausgeschlossen.",
    "faqQ8Title": "Fallen bei der Pro-Lifetime-Lizenz wirklich keine Abogebühren an?",
    "faqQ8Body": "Ja, garantiert. Wir glauben, dass Privatsphäre nicht an monatliche Gebühren gekoppelt sein darf. Für einmalig $8.99 erhalten Sie unbegrenzte Dateispeicherung, 4K-Streaming und PC-Android-Synchronisation auf Lebenszeit, inklusive aller kommenden v1.x-Updates.",
    "faqQ9Title": "Welche Medien- und Dateiformate werden unterstützt?",
    "faqQ9Body": "HiddenData unterstützt alle gängigen Bildformate (JPEG, PNG, WebP, GIF, SVG, BMP, HEIC/HEIF), Videoformate (MP4, WebM, MKV, MOV), Audioformate (MP3, WAV, FLAC, AAC, OGG) sowie beliebige Dokumentdateien (PDF, ZIP, TXT) als verschlüsselte .enc-Container.",
    "faqQ10Title": "Wie schützt der One-Touch-Sichtschutz vor Schulterblicken in der Öffentlichkeit?",
    "faqQ10Body": "In Zügen oder Cafés droht oft unerwünschtes Mitlesen. HiddenData bietet einen Notfall-Sichtschutz: Ein Tastendruck oder Klick auf das Schild-Symbol legt in unter 5 Millisekunden einen blickdichten Weichzeichner über die Ansicht und friert die Decoder ein, bis Sie sich wieder sicher fühlen.",
