    "secArchHeroSub": "Analyse technique approfondie du coffre Zero-Knowledge HiddenData : streaming AEAD par blocs de 64 Ko, 0 octet sur disque, rotation atomique des clés V3 et isolation au moindre privilège Google Drive.",
